import {ASSETS,ASSET_BY_ID,TAGS,RATING_XP} from './sim-catalog.js';
import {buildWorld,freshSimulation,syncParticipants,seedFactions,maxHP,economy,definition,previewOrders,validateOrder,addGMAsset,upgradeRating,planControlledAssets,populateControlledAssets} from './simulation.js';
import {advanceTurns,MAX_BATCH_TURNS} from './sim-batch.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const actions={wait:'Hold position',buy:'Buy asset',attack:'Attack rival faction',expand:'Expand influence',move:'Move / transport asset',seize:'Seize location',repair:'Repair asset',repairFaction:'Repair faction',sell:'Sell asset',refit:'Refit asset',use:'Use economic ability',home:'Relocate home'};
const goalNames={expand:'Expand influence',peace:'Peaceable kingdom',force:'Military conquest',wealth:'Commercial expansion',cunning:'Intelligence coup',seize:'Seize a location',blood:'Blood the enemy',destroy:'Destroy the foe',valor:'Invincible valor'};
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const field=(label,content)=>`<label class="field">${label}${content}</label>`;
const number=(name,value,min=0,max=99999)=>`<input name="${name}" type="number" value="${esc(value)}" min="${min}" max="${max}" step="1" required>`;
export function mountSimulation({getData,getSaved,replaceSaved,commit,invalidate,focusLocation}){
 let tab='overview',selected='',busy=false,status='',orderDraft=null,assetSelected='',worldData=null,worldCache=null,scaleHoldings=false,turnCount=1,batchRunning=false,stopRequested=false;
 const dialog=document.createElement('dialog');dialog.id='simulation-dialog';dialog.setAttribute('aria-labelledby','simulation-title');document.body.append(dialog);
 const state=()=>{const data=getData(),sim=data?._driftAtlas?.simulation;if(data!==worldData||!worldCache){worldData=data;worldCache=buildWorld(data||{});}return {data,sim,world:worldCache,saved:getSaved(),catalog:data?._driftAtlas?.factions||{}};};
 const name=(id,s)=>s.catalog[id]?.name||s.sim?.factions[id]?.name||'Former faction';
 const locName=(id,s)=>{const l=s.world.byId.get(id);return l?`${s.world.systems.get(l.systemId)?.name||''} / ${l.name}`:'Location unavailable';};
 function selectFaction(s){if(!s.sim?.factions[selected]||s.sim.factions[selected].archived)selected=Object.keys(s.sim?.factions||{}).find(id=>!s.sim.factions[id].archived)||'';}
 function locationOptions(s,value){return option('','Choose location',value)+s.world.locations.map(l=>option(l.id,locName(l.id,s),value)).join('');}
 function factionOptions(s,value,exclude){return Object.entries(s.sim.factions).filter(([id,f])=>id!==exclude&&!f.archived).map(([id])=>option(id,name(id,s),value)).join('');}
 function assetOptions(s,id,value){return option('','Choose asset',value)+s.sim.assets.filter(a=>a.factionId===id).map(a=>option(a.id,`${definition(a)?.name||a.template} · ${s.world.byId.get(a.locationId)?.name||'Missing location'} · ${a.hp} HP`,value)).join('');}
 const templateOptions=value=>ASSETS.map(a=>option(a.id,`${a.name} · ${a.stat[0].toUpperCase()}${a.level} · ${a.cost} cr · TL${a.tl}${a.manual?' · GM ability':''}`,value)).join('');
 function describe(o,s){if(!o)return 'Automatic';const a=s.sim.assets.find(a=>a.id===o.assetId);return `${actions[o.action]||o.action}${o.template?' · '+(ASSET_BY_ID[o.template]?.name||o.template):''}${a?' · '+definition(a)?.name:''}${o.targetFaction?' · '+name(o.targetFaction,s):''}${o.locationId?' → '+locName(o.locationId,s):''}`;}
 function clock(){const sim=getData()?._driftAtlas?.simulation,el=document.querySelector('#simulation-clock');if(el){el.hidden=!sim;el.textContent=sim?`◷ Turn ${sim.turn} · Day ${sim.days}`:'';}}
 async function change(fn,message='Saved on this device.'){if(busy)return;busy=true;try{await fn();invalidate();clock();const ok=await commit();status=ok?message:'Changes are in memory, but could not save. Export the map from Save / Load before closing.';}catch(e){status=e.message;}finally{busy=false;if(dialog.open)render();}}
 const advanceLabel=()=>turnCount===1?'Advance turn →':`Advance ${turnCount} turns →`;
 const undoLabel=sim=>{const count=sim.undo?sim.turn-sim.undo.simulation.turn:1;return count>1?`Undo last ${count} turns`:'Undo last turn';};
 function stopBatch(){if(!batchRunning)return;stopRequested=true;const button=dialog.querySelector('[data-action="stop-batch"]');if(button){button.disabled=true;button.textContent='Stopping…';}}
 async function runTurns(){
  if(busy)return;
  const input=dialog.querySelector('#sim-turn-count');if(!input.reportValidity())return;
  const count=input.valueAsNumber;if(!Number.isInteger(count)||count<1||count>MAX_BATCH_TURNS)return;
  turnCount=count;busy=true;batchRunning=true;stopRequested=false;status=`Advancing 0 / ${count} turns…`;
  render();let applied=false;
  try{
   const s=state(),working=structuredClone(s.sim);syncParticipants(working,s.data,s.saved);
   const result=await advanceTurns(working,s.world,s.saved,count,{
    shouldStop:()=>stopRequested,
    onProgress:completed=>{status=`Advancing ${completed} / ${count} turns…`;const progress=dialog.querySelector('#sim-batch-progress');if(progress)progress.value=completed;const message=dialog.querySelector('#sim-status');if(message)message.textContent=status;}
   });
   if(!result.completed){status='Stopped before advancing any turns.';return;}
   s.data._driftAtlas.simulation=result.simulation;applied=true;replaceSaved(result.ownership);invalidate();clock();tab='history';orderDraft=null;
   const ok=await commit();
   status=!ok?'Turns resolved in memory, but could not save. Export the map from Save / Load before closing.':result.completed<count?`Stopped. ${result.completed} of ${count} turns resolved and saved.`:count===1?'Turn resolved and saved.':`${count} turns resolved and saved.`;
  }catch(e){status=applied?'Turns resolved in memory, but saving failed. Export the map from Save / Load before closing.':`No turns applied. ${e.message}`;}
  finally{busy=false;batchRunning=false;dialog.removeAttribute('aria-busy');if(dialog.open)render();}
 }
 dialog.addEventListener('cancel',e=>{if(batchRunning){e.preventDefault();stopBatch();}});
 dialog.addEventListener('input',e=>{if(e.target.id!=='sim-turn-count'||busy)return;if(e.target.validity.valid){turnCount=e.target.valueAsNumber;dialog.querySelector('[data-action="advance"]').textContent=advanceLabel();}});
 function logAdjustment(sim,text,factionId){sim.undo=null;sim.history.push({turn:sim.turn,day:sim.days,adjustment:true,events:[{factionId,text,locationId:null}]});}
 function incomeSetting(value='territory'){return field('FACTION INCOME',`<select name="incomeModel">${option('territory','SWN income + controlled territory',value)}${option('standard','Standard SWN income only',value)}</select>`);}
 function territoryBreakdown(s,e){return s.sim.incomeModel==='standard'?'<p class="help">Standard SWN income only. Territory income is disabled in Turn settings.</p>':`<details class="sim-detail"><summary>Territory income · ${e.territoryDetails.length} controlled locations</summary><div class="sim-holdings-preview">${e.territoryDetails.map(l=>`<p><b>${esc(locName(l.locationId,s))}</b> · +${l.credits} credits/turn<br>${esc(l.reason)}${l.capitalBonus?' · includes +1 capital':''}</p>`).join('')||'<p>No controlled locations.</p>'}</div></details><p class="help">Territorial income is a map-scale campaign adaptation. Income follows orbital ownership; a newly captured location pays from the next turn.</p>`;}
 function intro(s){const count=Object.keys(s.catalog).length;return `<div class="sim-welcome"><span class="eyebrow">A LIVING SECTOR</span><h3>Let the world take its turn.</h3><p>Organizations build fleets, cultivate influence, fight rivals, and struggle for control while your crew pursues its own story.</p><div class="sim-steps"><article><b>01 · Prepare</b><p>Use your map’s factions and ownership. Every controlled planet, station, and orbital receives local assets matched to its population, technology, and role. Capitals receive the largest starting package.</p></article><article><b>02 · Give orders</b><p>Let factions act automatically or choose their orders. Review plans before advancing one campaign month.</p></article><article><b>03 · Watch it unfold</b><p>Read rolled outcomes, follow events to the map, and undo the last turn when needed.</p></article></div><p>${count?`${count} existing factions found. Your current ownership is preserved.`:'There are no campaign factions yet. Generate four Greco-Roman factions at separate worlds, or create your own in Menu → Factions.'}</p><form data-form="start"><div class="sim-grid">${field('TURN CONTROL',`<select name="mode">${option('auto','Automatic decisions with GM overrides','auto')}${option('manual','Manual orders for every faction','')}</select>`)}${field('DAYS PER TURN',number('days',30,1,365))}${incomeSetting()}</div><button class="primary" type="submit">${count?'Start with existing factions':'Generate factions & start'}</button></form><p class="help">Progress advances only when you press Advance turn. Saves and JSON exports include the simulation.</p></div>`;}
 function overview(s){const sim=s.sim,entries=Object.entries(sim.factions).filter(([,f])=>!f.archived);return `${holdingsSetup(s)}<div class="sim-metrics"><article><small>CAMPAIGN CLOCK</small><b>Day ${sim.days}</b><span>${sim.turnDays} days / turn</span></article><article><small>ACTIVE FACTIONS</small><b>${entries.filter(([,f])=>f.hp>0).length}</b><span>${entries.length} participants</span></article><article><small>ASSETS IN PLAY</small><b>${sim.assets.length}</b><span>${sim.assets.filter(a=>a.template==='base').length} bases of influence</span></article></div><div class="sim-section-heading"><h3>Sector powers</h3><button class="button" data-action="sync">Sync map factions</button></div><div class="sim-faction-cards">${entries.map(([id,f])=>{const e=economy(sim,id,{world:s.world,saved:s.saved}),claims=s.world.locations.filter(l=>s.saved[l.id]?.factionId===id).length;return `<button class="sim-faction-card" data-faction="${esc(id)}" style="--faction-color:${/^#[0-9a-f]{6}$/i.test(s.catalog[id]?.color)?s.catalog[id].color:'#79dbcf'}"><span class="sim-card-title">${esc(name(id,s))}<small>${f.hp<=0?'COLLAPSED':esc(f.style.toUpperCase())}</small></span><span class="sim-rating-row"><b>F ${f.force}</b><b>C ${f.cunning}</b><b>W ${f.wealth}</b></span><span>${f.hp}/${maxHP(f)} HP · ${f.credits} credits · ${e.net>=0?'+':''}${e.net}/turn</span><small>${claims} controlled locations · ${sim.assets.filter(a=>a.factionId===id).length} assets</small>${f.seizing?`<small>Occupying ${esc(s.world.byId.get(f.seizing.locationId)?.name)} · ${f.seizing.hold}/3</small>`:''}</button>`;}).join('')}</div><section class="sim-settings"><h3>Turn settings</h3><form data-form="settings"><div class="sim-grid">${field('CONTROL',`<select name="mode">${option('auto','Automatic decisions',sim.mode)}${option('manual','Manual orders',sim.mode)}</select>`)}${field('DAYS PER TURN',number('days',sim.turnDays,1,365))}${incomeSetting(sim.incomeModel||'territory')}</div><button class="button">Save settings</button></form><p class="help">One action type per faction per turn. Automatic plans adapt to earlier factions’ results. A monthly turn is the default; Starfinder travel rolls remain separate.</p></section>${sim.history.length?`<h3>Latest dispatch</h3>${report(sim.history.at(-1),s)}`:''}`;}
 function holdingsSetup(s){
  const plan=planControlledAssets(s.sim,s.world,s.saved,{scaleRatings:scaleHoldings});
  if(!plan.locations.length)return '';
  const deficits=Object.entries(plan.economies).filter(([,e])=>e.after.net<0);
  return `<section class="sim-settings sim-holdings"><span class="eyebrow">DEVELOP YOUR TERRITORY</span><h3>Assets across your holdings</h3><p>${plan.locations.length} controlled locations have not been initialized. Add ${plan.assets.length} assets, including local bases, without replacing existing units.</p><label class="sim-checkbox"><input id="sim-scale-holdings" type="checkbox" ${scaleHoldings?'checked':''}> Scale faction ratings and starting reserves to support these holdings</label><p class="help">Optional GM setup: raise ratings up to 8 to match deployed assets and add a three-turn deficit reserve if needed. Existing damage is preserved.</p><details class="sim-detail"><summary>Review locations and economy</summary><div class="sim-holdings-preview">${plan.locations.map(l=>`<p><b>${esc(locName(l.locationId,s))}</b><br>${esc(name(l.factionId,s))} · ${esc(l.role)}<br>${l.templates.length?l.templates.map(t=>esc(t==='base'?'Base of Influence':ASSET_BY_ID[t].name)).join(', '):'Existing assets already cover this package.'}</p>`).join('')}</div>${Object.entries(plan.economies).map(([id,e])=>`<p><b>${esc(name(id,s))}</b> · projected ${e.after.net>=0?'+':''}${e.after.net} credits/turn (currently ${e.before.net>=0?'+':''}${e.before.net})${scaleHoldings?` · F ${plan.profiles[id].force} / C ${plan.profiles[id].cunning} / W ${plan.profiles[id].wealth} · ${plan.profiles[id].credits} credits`:''}</p>`).join('')}</details>${deficits.length?`<p class="sim-notice">${deficits.map(([id])=>esc(name(id,s))).join(', ')} will run a deficit under SWN asset limits. Review ratings, reserves, and asset counts before advancing turns.</p>`:''}<button class="primary" data-action="populate-holdings">Populate controlled locations</button><p class="help">One-time setup per location. No purchase cost or turn is spent. After initialization, sold, moved, or destroyed assets are never recreated by this action. Existing orders and ownership are preserved; this setup replaces the last-turn undo.</p></section>`;
 }
 function orders(s){const sim=s.sim,plans=previewOrders(sim,s.world,s.saved);const f=sim.factions[selected];if(!f)return '<p>No participating factions. Sync map factions from Overview.</p>';const o=orderDraft||sim.orders[selected]||plans[selected]||{action:'wait'},kind=o.action;return `<div class="sim-split"><section><h3>Next turn’s intentions</h3><div class="sim-order-list">${Object.entries(plans).map(([id,p])=>`<button data-order-faction="${esc(id)}" class="${id===selected?'active':''}"><b>${esc(name(id,s))}</b><span>${esc(describe(p,s))}</span><small>${sim.orders[id]?'GM ORDER':sim.mode==='manual'||sim.factions[id].control==='manual'?'MANUAL · HOLD IF NOT QUEUED':'AUTOMATIC · MAY ADAPT'}</small></button>`).join('')}</div></section><section class="sim-editor"><h3>Order for ${esc(name(selected,s))}</h3><form data-form="order">${field('ACTION',`<select name="action" id="sim-order-action">${Object.entries(actions).map(([key,label])=>option(key,label,kind)).join('')}</select>`)}${['buy','refit'].includes(kind)?field('ASSET TEMPLATE',`<select name="template">${templateOptions(o.template||'security-personnel')}</select>`):''}${['move','repair','sell','refit','use'].includes(kind)?field(kind==='move'?'TRANSPORT / MOBILE ASSET':'ASSET',`<select name="assetId">${assetOptions(s,selected,o.assetId)}</select>`):''}${kind==='move'?field('CARGO · SELECT SAME ASSET TO MOVE ITSELF',`<select name="cargoId">${assetOptions(s,selected,o.cargoId||o.assetId)}</select>`):''}${['buy','attack','expand','move','seize','home'].includes(kind)?field('LOCATION',`<select name="locationId">${locationOptions(s,o.locationId||f.home)}</select>`):''}${kind==='attack'?field('RIVAL FACTION',`<select name="targetFaction">${factionOptions(s,o.targetFaction,selected)}</select>`):''}${kind==='expand'?field('BASE HP · 1 CREDIT EACH',number('hp',o.hp||4,1,maxHP(f))):''}${kind==='repair'?field('REPAIR BATCHES · COST 1 + 2 + 3 …',number('amount',o.amount||1,1,10)):''}<div class="sim-actions"><button class="primary">Queue order</button><button type="button" class="button" data-action="clear-order">Use ${sim.mode==='auto'?'automatic plan':'hold position'}</button></div></form><p class="help">Attack uses every ready attacker at the selected location. The defender chooses its strongest eligible defender. Movement range uses drift-lane jumps. New purchases become ready next turn.</p></section></div>`;}
 function factionSheet(s){const f=s.sim.factions[selected];if(!f)return '<p>No faction selected.</p>';const e=economy(s.sim,selected,{world:s.world,saved:s.saved});return `${field('FACTION',`<select id="sim-faction-choice">${factionOptions(s,selected)}</select>`)}<div class="sim-split"><section><h3>Command profile</h3><form data-form="profile"><div class="sim-grid three">${['force','cunning','wealth'].map(k=>field(k.toUpperCase(),number(k,f[k],1,8))).join('')}${field('CURRENT HP',number('hp',f.hp,0,100))}${field('CREDITS',number('credits',f.credits))}${field('EXPERIENCE',number('xp',f.xp))}</div>${field('HOME LOCATION',`<select name="home">${locationOptions(s,f.home)}</select>`)}<div class="sim-grid">${field('DECISION STYLE',`<select name="style">${['expansionist','aggressive','mercantile','cautious'].map(k=>option(k,k[0].toUpperCase()+k.slice(1),f.style)).join('')}</select>`)}${field('CONTROL',`<select name="control">${option('auto','Follow turn settings',f.control)}${option('manual','Manual orders only',f.control)}</select>`)}</div>${field('AUTOMATED FACTION TAG',`<select name="tag">${option('','No automated tag',f.tag)}${TAGS.map(t=>option(t,t,f.tag)).join('')}</select>`)}<label class="sim-checkbox"><input type="checkbox" name="absorbs" ${f.absorbs?'checked':''}> Divert incoming damage to a local base</label><p class="help">Base damage also damages faction HP. These fields are GM adjustments; use orders for normal play.</p><button class="button">Save faction changes</button></form><div class="sim-actions">${['force','cunning','wealth'].map(k=>`<button class="button" data-upgrade="${k}" ${f[k]>=8?'disabled':''}>Raise ${k} · ${f[k]>=8?'max':RATING_XP[f[k]+1]+' XP'}</button>`).join('')}</div></section><section><h3>Economy</h3><dl class="sim-dl"><dt>Base income</dt><dd>${e.base}</dd><dt>Territory income</dt><dd>+${e.territory}</dd><dt>Asset income</dt><dd>+${e.bonus}</dd><dt>Overextension</dt><dd>−${e.over}</dd><dt>Maintenance</dt><dd>−${e.upkeep}</dd><dt>Expected net</dt><dd>${e.net}</dd></dl><p class="help">⌈Wealth ÷ 2⌉ + ⌊(Force + Cunning) ÷ 4⌋, plus territory and asset income, minus excess assets and upkeep. These are faction credits, not personal credits.</p>${territoryBreakdown(s,e)}<h3>Relationships</h3><form data-form="relations">${Object.entries(s.sim.factions).filter(([id,other])=>id!==selected&&!other.archived).map(([id])=>field(esc(name(id,s)),`<select name="${esc(id)}">${['neutral','ally','hostile'].map(v=>option(v,v[0].toUpperCase()+v.slice(1),f.relations[id]||'neutral')).join('')}</select>`)).join('')}<button class="button">Save relationships</button></form><p class="help">Allies permit imports and do not resist seizures. Hostile factions attack when able; aggressive factions may start conflicts with neutral rivals.</p><h3>Current objective</h3><form data-form="goal">${field('GOAL',`<select name="type">${Object.entries(goalNames).map(([k,n])=>option(k,n,f.goal?.type)).join('')}</select>`)}<div class="sim-grid three">${field('PROGRESS',number('progress',f.goal?.progress||0))}${field('TARGET',number('target',f.goal?.target||1,1))}${field('XP REWARD',number('reward',f.goal?.reward||1,1,20))}</div><button class="button">Set objective</button></form><p class="help">Goal thresholds and rewards are GM-set. Completed goals grant XP; automatic factions invest it in their strongest rating. Setting a goal here is a GM adjustment.</p></section></div>`;}
 function assets(s){const sim=s.sim,owned=sim.assets.filter(a=>a.factionId===selected);if(!owned.some(a=>a.id===assetSelected))assetSelected=owned[0]?.id||'';const a=owned.find(a=>a.id===assetSelected);return `${field('FACTION',`<select id="sim-faction-choice">${factionOptions(s,selected)}</select>`)}<div class="sim-split"><section><h3>Deployed assets</h3><div class="sim-asset-list">${owned.map(a=>{const d=definition(a);return `<button data-asset="${esc(a.id)}" class="${a.id===assetSelected?'active':''}"><b>${esc(d?.name||a.template)} <span>${a.hp}/${a.maxHp} HP</span></b><span>${esc(locName(a.locationId,s))}</span><small>${a.hidden?'HIDDEN · ':''}${a.arrears?'UPKEEP UNPAID · ':''}${a.readyTurn>sim.turn?'READY TURN '+a.readyTurn+' · ':''}${d?.manual?'GM SPECIAL ABILITY':esc(d?.kind)}</small></button>`;}).join('')||'<p>No assets. Buy one with an order or add a GM asset below.</p>'}</div><details class="sim-detail"><summary>Add a GM asset</summary><p class="help">Adds an asset without spending credits or a turn. Use for initial setup, special effects, or player achievements.</p><form data-form="add-asset">${field('ASSET',`<select name="template">${option('base','Base of Influence','')}${templateOptions('security-personnel')}</select>`)}${field('LOCATION',`<select name="locationId">${locationOptions(s,sim.factions[selected]?.home)}</select>`)}${field('BASE HP (FOR BASES ONLY)',number('hp',4,1,100))}<button class="button">Add asset</button></form></details></section><section class="sim-editor">${a?assetEditor(a,s):'<h3>Select an asset</h3>'}</section></div>`;}
 function assetEditor(a,s){const d=definition(a);return `<h3>${esc(d.name)}</h3><p>${esc(d.effect||'Standard asset; no additional special ability.')}</p><dl class="sim-dl"><dt>Attack</dt><dd>${d.attack?esc(d.attackStat+' vs '+d.defenseStat+' · '+d.attack):'None'}</dd><dt>Counter</dt><dd>${esc(d.counter||'None')}</dd><dt>Upkeep</dt><dd>${d.upkeep||0}</dd></dl>${d.manual?'<p class="sim-notice">This template’s special ability needs GM adjudication. Its basic numerical stats are tracked; apply special outcomes with the adjustments below and faction sheets.</p>':''}<form data-form="asset"><div class="sim-grid">${field('CURRENT HP',number('hp',a.hp,0,a.maxHp))}${field('READY ON TURN',number('readyTurn',a.readyTurn))}</div>${field('OWNER',`<select name="factionId">${factionOptions(s,a.factionId)}</select>`)}${field('LOCATION',`<select name="locationId">${locationOptions(s,a.locationId)}</select>`)}<label class="sim-checkbox"><input name="hidden" type="checkbox" ${a.hidden?'checked':''}> Hidden asset</label>${field('ADJUDICATION NOTE','<input name="note" maxlength="300" placeholder="Player action or special effect…">')}<p class="help">Changing base HP applies the same damage to faction HP; repairing a base does not restore faction HP. Setting HP to zero removes the asset.</p><button class="button">Apply GM adjustment</button></form>`;}
 function report(r,s){return `<article class="sim-report"><h4>${r.adjustment?'GM adjustment':'Turn '+r.turn} <span>Day ${r.day}</span></h4>${r.initiative?`<p class="help">Initiative: ${r.initiative.map(id=>esc(name(id,s))).join(' → ')}</p>`:''}<ol>${r.events.map(e=>`<li><b>${esc(name(e.factionId,s))}</b><span>${esc(e.text)}</span>${s.world.byId.has(e.locationId)?`<button data-location="${esc(e.locationId)}">${esc(s.world.byId.get(e.locationId).name)} ↗</button>`:''}</li>`).join('')}</ol></article>`;}
 function history(s){return `<div class="sim-section-heading"><h3>Campaign chronicle</h3><button class="button" data-action="export-history">Export chronicle</button></div><p class="help">Rolls, credit changes, asset losses, and ownership changes are recorded here. Advance turns between sessions, then use these events as news and adventure hooks.</p>${s.sim.history.length?[...s.sim.history].reverse().slice(0,100).map(r=>report(r,s)).join(''):'<div class="sim-empty">The next chapter is unwritten. Review Orders, then advance your first turn.</div>'}${s.sim.history.length>100?'<p>Showing the latest 100 entries. Export contains the full chronicle.</p>':''}`;}
 function rules(){return `<div class="sim-rules"><h3>SWN faction turns in Drift Atlas</h3><p>Based on Stars Without Number Revised’s faction system and the <a href="https://d0ngiovanni.github.io/swn-faction-spreadsheet/" target="_blank" rel="noopener">faction spreadsheet reference ↗</a>. This is a GM-facing campaign simulator, not Starfinder encounter balance.</p><h4>Automated core</h4><ul><li>Force, Cunning, Wealth, rating-based faction HP, credits, XP, income, upkeep, and excess-asset penalties.</li><li>One faction action each turn, with a randomly chosen first faction. Purchase/refit assets activate next turn. An attack order uses every ready attacker at its location.</li><li>Combat uses d10 + the attacking attribute versus d10 + the target attribute. Ties apply both damage and counterdamage. The defender chooses an eligible defender; its base can absorb damage when configured.</li><li>Base damage also harms the faction. Factions at zero HP collapse and release their locations.</li><li>Expansion requires an existing asset and costs 1 credit per base HP. Rivals that match or beat the expansion roll may retaliate.</li><li>Seizure defeats resistance, then holds a visible asset for three turns before changing orbital ownership.</li><li>Repair, sale, refit, home relocation, transport ranges/costs, economic abilities, supported tags, and tracked objectives.</li></ul><h4>Map adaptation</h4><p>A faction location is an individual planet, moon, station, or other imported orbital. A system without orbitals is one location. This finer scale preserves split system ownership. SWN movement hex ranges are mapped to shortest drift-lane jumps; moves within a system use zero jumps. Moves consume a faction turn, not a Starfinder travel roll. Unknown tech levels default to TL4 for faction purchases and can be overridden through source data.</p><h4>Territory income (campaign adaptation)</h4><p>Standard SWN rating income remains ⌈Wealth / 2⌉ + ⌊(Force + Cunning) / 4⌋. The default adds controlled territory income; select Standard SWN income only in Turn settings to disable this addition. Asset costs, upkeep, overextension, and economic ability rolls are unchanged.</p><ul><li>Populated worlds: 1 credit below 100,000 inhabitants; 2 below 100 million; 3 below 1 billion; 4 at a billion or more. Technology caps this at 1 for TL0–1, 2 for TL2, 3 for TL3, and 4 for TL4. TL5 adds 1 to productive worlds.</li><li>Operating facilities contribute 2 credits. Mines, trade/industrial stations, and research bases contribute 3 at TL4 or higher; other bases contribute 3 at TL5.</li><li>A productive, owned capital adds 1. Uninhabited worlds, abandoned facilities, ruins, empty belts, and stars yield 0. Unknown planet population defaults to a modest 1 before technology; unknown moon population defaults to 0. Unknown TL defaults to 4.</li><li>Each orbital pays only its controlling faction, once per turn, based on ownership at turn start. Bases of Influence and additional units do not create territory income. Captures begin paying the following turn. Existing saves use this model automatically unless Standard SWN is explicitly selected; past turns and balances are not rewritten.</li></ul><h4>GM adjudication</h4><p>The catalog contains ${ASSETS.length} numerical asset templates. Templates marked “GM ability” track basic stats but do not automate their special effects. Medical Center resurrection, multi-cargo transports, optional reroll timing, additional tags, and narrative permission exceptions also need GM adjudication. The current move order transports one chosen cargo; attack orders use automatic defender selection. Use asset and faction adjustments for these effects. Goal targets/rewards are editable; default goals use expansion (1 XP) or four peaceful turns (1 XP).</p><p>Automatic behavior and starting packages are campaign defaults, not prescribed SWN rules. Every controlled location gets a local Base of Influence and one to three assets suited to population, technology, and function. Capitals receive a full-strength base and up to four distinct assets. Uninhabited worlds receive a small outpost. New factions start from ratings 3/2/1, scaled up to 8 to meet their starting assets and category counts; reserves start at eight credits plus three turns of any deficit. SWN upkeep and overextension still apply. Existing campaigns use Populate controlled locations in Overview; rating/reserve scaling is optional. Initialization is remembered per location, so losses and relocations are not replenished, and conquest does not generate free assets. Automatic decisions are local rules, not an external AI service. You decide when time advances; no background turns run.</p><h4>Saving and undo</h4><p>Simulation data is saved with the map on this device and travels with sector/cluster JSON exports. Set the Turns field to advance 1–100 turns sequentially. Stop finishes at a turn boundary and saves completed turns. Queued orders are consumed once; subsequent turns follow automatic/manual settings, and ongoing occupations continue normally. Every turn has its own chronicle report. Undo restores the state before the entire most recent run, including ownership and dice state. GM adjustments invalidate turn undo. Sector extraction includes local assets and shared faction finances; importing separate campaigns keeps the destination campaign clock and existing faction finances.</p></div>`;}
 function render(){const s=state();selectFaction(s);const sim=s.sim;dialog.innerHTML=`<div class="sim-header"><div><span class="eyebrow">CAMPAIGN SIMULATION</span><h2 id="simulation-title">The living sector<span class="accent">.</span></h2></div><button class="button" data-action="close">← Menu</button></div>${sim?`<div class="sim-command"><div><b>Turn ${sim.turn}</b><span>Day ${sim.days} · ${sim.mode==='auto'?'Automatic decisions':'Manual orders'}</span></div><div class="sim-actions"><button class="button" data-action="undo" ${sim.undo?'':'disabled'}>${undoLabel(sim)}</button><div class="sim-advance-controls"><label for="sim-turn-count">TURNS<input id="sim-turn-count" type="number" min="1" max="${MAX_BATCH_TURNS}" step="1" inputmode="numeric" required value="${turnCount}" aria-describedby="sim-advance-help"></label><button class="primary" data-action="advance" ${busy?'disabled':''}>${advanceLabel()}</button></div></div></div><div class="sim-advance-info"><p id="sim-advance-help">1–${MAX_BATCH_TURNS} turns per run. Queued orders apply once; later turns follow faction control settings. Undo reverses the entire run.</p>${batchRunning?`<div class="sim-batch-status"><progress id="sim-batch-progress" max="${turnCount}" value="0" aria-label="Turns completed"></progress><button class="button" data-action="stop-batch">Stop after current turn</button></div>`:''}</div><div class="sim-tabs" role="tablist">${[['overview','Overview'],['orders','Orders'],['factions','Faction sheets'],['assets','Assets'],['history','Chronicle'],['rules','Rules']].map(([key,label])=>`<button role="tab" aria-selected="${tab===key}" data-sim-tab="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}</div>`:''}<p id="sim-status" role="status">${esc(status)}</p><div class="sim-body">${!sim?intro(s):tab==='overview'?overview(s):tab==='orders'?orders(s):tab==='factions'?factionSheet(s):tab==='assets'?assets(s):tab==='history'?history(s):rules()}</div>`;if(batchRunning){dialog.setAttribute('aria-busy','true');for(const el of dialog.querySelectorAll('button,input,select,textarea'))if(el.dataset.action!=='stop-batch')el.disabled=true;}clock();}
 async function start(form){const s=state();if(s.sim)return;if(!Object.keys(s.catalog).length)seedFactions(s.data,s.saved);const sim=freshSimulation(crypto.getRandomValues(new Uint32Array(1))[0]);sim.mode=form.get('mode');sim.incomeModel=form.get('incomeModel')||'territory';sim.turnDays=Number(form.get('days'));syncParticipants(sim,s.data,s.saved);if(!Object.keys(sim.factions).length)throw Error('No suitable map locations to host factions.');s.data._driftAtlas.simulation=sim;selected=Object.keys(sim.factions)[0];tab='overview';const toggle=document.querySelector('[data-faction-toggle]');if(toggle&&!toggle.checked){toggle.checked=true;toggle.dispatchEvent(new Event('change'));}}
 dialog.addEventListener('submit',e=>{e.preventDefault();if(busy)return;const form=e.target,kind=form.dataset.form,v=new FormData(form);if(!form.reportValidity())return;change(async()=>{const s=state(),sim=s.sim,f=sim?.factions[selected];
 if(kind==='start'){await start(v);return;}
 if(kind==='settings'){sim.undo=null;sim.mode=v.get('mode');sim.incomeModel=v.get('incomeModel')||'territory';sim.turnDays=Number(v.get('days'));return;}
 if(kind==='order'){const o=Object.fromEntries(v);for(const key of ['hp','amount'])if(o[key]!==undefined)o[key]=Number(o[key]);const err=validateOrder(sim,selected,o,s.world,s.saved);if(err)throw Error(err);sim.orders[selected]=o;orderDraft=null;return;}
 if(kind==='profile'){const next={...f};for(const key of ['force','cunning','wealth','hp','credits','xp'])next[key]=Number(v.get(key));if(next.hp>maxHP(next))throw Error('Current HP exceeds the maximum for these ratings.');if(!s.world.byId.has(v.get('home')))throw Error('Choose a valid home location.');for(const key of ['home','style','control','tag'])next[key]=v.get(key);next.absorbs=v.has('absorbs');sim.factions[selected]=next;logAdjustment(sim,'Faction profile adjusted by the GM.',selected);return;}
 if(kind==='relations'){for(const [id,value] of v){f.relations[id]=value;if(sim.factions[id])sim.factions[id].relations[selected]=value;}logAdjustment(sim,'Diplomatic relationships updated.',selected);return;}
 if(kind==='goal'){f.goal={type:v.get('type'),progress:Number(v.get('progress')),target:Number(v.get('target')),reward:Number(v.get('reward'))};logAdjustment(sim,'Objective set: '+goalNames[f.goal.type]+'.',selected);return;}
 if(kind==='add-asset'){const location=v.get('locationId');if(!s.world.byId.has(location))throw Error('Choose a valid location.');if(v.get('template')==='base'&&Number(v.get('hp'))>maxHP(f))throw Error('Base HP exceeds faction maximum.');if(v.get('template')==='base'&&sim.assets.some(a=>a.template==='base'&&a.factionId===selected&&a.locationId===location))throw Error('This faction already has a base here.');const a=addGMAsset(sim,selected,v.get('template'),location,Number(v.get('hp')));assetSelected=a.id;logAdjustment(sim,'GM added '+definition(a).name+'.',selected);return;}
 if(kind==='asset'){const a=sim.assets.find(a=>a.id===assetSelected);if(!a)throw Error('Asset no longer exists.');if(!s.world.byId.has(v.get('locationId')))throw Error('Choose a valid location.');const hp=Number(v.get('hp'));if(a.template==='base'&&hp<a.hp){const owner=sim.factions[a.factionId];owner.hp=Math.max(0,owner.hp-(a.hp-hp));if(owner.hp===0)for(const edit of Object.values(s.saved))if(edit.factionId===a.factionId)delete edit.factionId;}a.hp=hp;a.readyTurn=Number(v.get('readyTurn'));a.hidden=v.has('hidden');a.locationId=v.get('locationId');a.factionId=v.get('factionId');a.arrears=0;if(!hp)sim.assets=sim.assets.filter(x=>x!==a);logAdjustment(sim,`${definition(a).name} adjusted. ${v.get('note')||''}`,a.factionId);return;}
 });});
 dialog.addEventListener('change',e=>{if(busy)return;if(e.target.id==='sim-scale-holdings'){scaleHoldings=e.target.checked;render();}else if(e.target.id==='sim-faction-choice'){selected=e.target.value;orderDraft=null;render();}else if(e.target.id==='sim-order-action'){const v=new FormData(e.target.form);orderDraft={...Object.fromEntries(v),action:e.target.value};render();}});
 dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='stop-batch'){stopBatch();return;}if(busy)return;if(b.dataset.simTab){tab=b.dataset.simTab;orderDraft=null;render();dialog.scrollTop=0;return;}if(b.dataset.faction){selected=b.dataset.faction;tab='factions';render();return;}if(b.dataset.orderFaction){selected=b.dataset.orderFaction;orderDraft=null;render();return;}if(b.dataset.asset){assetSelected=b.dataset.asset;render();return;}if(b.dataset.location){dialog.close();focusLocation(b.dataset.location);return;}if(b.dataset.upgrade){change(()=>{const s=state();upgradeRating(s.sim,selected,b.dataset.upgrade);logAdjustment(s.sim,'Spent XP to raise '+b.dataset.upgrade+'.',selected);});return;}
 const action=b.dataset.action;if(action==='close'){dialog.close();document.querySelector('#main-menu').showModal();return;}if(action==='advance'){runTurns();return;}
 if(action==='undo'){const count=state().sim.turn-(state().sim.undo?.simulation.turn??state().sim.turn);change(()=>{const s=state(),undo=s.sim.undo;if(!undo)throw Error('There is no turn to undo.');s.data._driftAtlas.simulation=undo.simulation;const edits=structuredClone(s.saved);for(const change of undo.changes||[]){if(edits[change.id]?.factionId===change.after){edits[change.id]||={};if(change.before)edits[change.id].factionId=change.before;else delete edits[change.id].factionId;}}replaceSaved(edits);tab='overview';},count>1?`${count} turns undone, including their dice state.`:'Last turn undone, including its dice state.');return;}
 if(action==='populate-holdings'){change(()=>{const s=state();const plan=populateControlledAssets(s.sim,s.world,s.saved,{scaleRatings:scaleHoldings});if(plan.locations.length){s.sim.history.push({turn:s.sim.turn,day:s.sim.days,adjustment:true,events:plan.locations.map(l=>({factionId:l.factionId,locationId:l.locationId,text:`Established ${l.role} presence: ${l.templates.length} assets added.`}))});}scaleHoldings=false;},'Controlled locations populated and saved.');return;}
 if(action==='sync'){change(()=>{const s=state();syncParticipants(s.sim,s.data,s.saved);s.sim.undo=null;},'Map factions synchronized.');return;}if(action==='clear-order'){change(()=>{delete state().sim.orders[selected];orderDraft=null;});return;}
 if(action==='export-history'){const s=state(),blob=new Blob([JSON.stringify({map:Object.values(s.data.sector||{})[0]?.name,turn:s.sim.turn,history:s.sim.history},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='drift-atlas-chronicle.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 });
 return {open(){tab='overview';status='';orderDraft=null;render();dialog.showModal();},refresh(){clock();if(dialog.open)render();},details(locationId){if(!getData()?._driftAtlas?.simulation)return '';const s=state();const system=s.world.systems.has(locationId);const assets=s.sim.assets.filter(a=>a.locationId===locationId||system&&s.world.byId.get(a.locationId)?.systemId===locationId);if(!assets.length)return '';return `<details class="sim-location-assets"><summary>Faction assets · ${assets.length}</summary>${assets.map(a=>`<p><b>${esc(definition(a)?.name||a.template)}</b> · ${esc(name(a.factionId,s))} · ${a.hp}/${a.maxHp} HP${system?' · '+esc(s.world.byId.get(a.locationId)?.name):''}${a.hidden?' · hidden (GM)':''}</p>`).join('')}</details>`;}};
}
